"""Local light/dark appearance and reference-led comparison cards."""
CSS='''
:root{--eios-bg:#f3f6fc;--eios-card:#fff;--eios-soft:#f5f7fb;--eios-ink:#102143;--eios-muted:#596c8c;--eios-line:#dbe4f1;--eios-blue:#eaf0ff;--eios-ref:#101f42}
#po-conditions .po-alt-heading h3,#po-conditions .po-alt-card h4,#po-conditions .po-alt-total,#po-conditions .po-alt-baseline strong,#po-conditions .po-draft-column h3,#po-conditions .po-column-total strong,#po-conditions .po-heading h2{font-family:var(--eios-display)!important}
body{background:var(--eios-bg);color:var(--eios-ink);font-variant-numeric:tabular-nums}#eios-theme-toggle{margin-left:auto;padding:8px 12px;border:1px solid var(--eios-line);border-radius:9px;background:var(--eios-card);color:var(--eios-ink);font-size:13px;white-space:nowrap}
.po-alternatives-table{padding:24px;background:var(--eios-bg);border:0;border-radius:16px;color:var(--eios-ink)}.po-alt-heading{display:flex;gap:14px;justify-content:space-between;align-items:center}.po-alt-heading h3{font-family:var(--eios-display)!important;font-size:clamp(25px,2.5vw,34px)!important;line-height:1.15;letter-spacing:-.035em;text-transform:none;margin:0!important}.po-alt-simulation{font-size:10px;font-weight:600;letter-spacing:.12em;border:1px solid #b5c7ff;background:var(--eios-blue);color:#1554d6;border-radius:24px;padding:8px 12px}.po-alt-intro{margin:9px 0 22px!important;color:var(--eios-muted);font-size:15px!important}
.po-alt-baseline{background:var(--eios-ref);color:#fff;padding:18px 22px;border:0;border-radius:17px;gap:14px;margin-bottom:22px}.po-alt-baseline>span:first-child{font-size:11px;font-weight:600;letter-spacing:.1em;color:#b6c7e4}.po-alt-baseline strong{font-family:var(--eios-display)!important;font-size:clamp(27px,3vw,42px);font-variant-numeric:tabular-nums}.po-alt-baseline>span:last-child{background:#ffffff1a;border-radius:20px;padding:7px 13px;font-size:13px;font-weight:600}
.po-alt-cards{gap:20px;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));align-items:stretch}.po-alt-card{container-type:inline-size;display:flex;flex-direction:column;border:1px solid var(--eios-line);border-radius:21px;padding:22px;background:var(--eios-card);overflow:hidden;box-shadow:0 2px 3px #14264305;color:var(--eios-ink)}.po-alt-tags{display:flex;justify-content:space-between;align-items:center;gap:7px;margin-bottom:16px;flex-wrap:wrap}.po-alt-ref{background:var(--eios-ref);color:#fff;border-radius:7px;padding:5px 9px;font-size:12px;font-weight:600;letter-spacing:.03em}.po-alt-quantity{background:var(--eios-soft);padding:5px 9px;border-radius:20px;margin:0!important;min-height:0;font-size:12px!important;color:var(--eios-muted)}.po-alt-card header{min-height:0}.po-alt-card h4{font-family:var(--eios-display)!important;font-size:23px;font-weight:650;letter-spacing:-.02em;line-height:1.18;margin:0}.po-alt-description{font-size:14px!important;line-height:1.45!important;color:var(--eios-muted);margin:8px 0 16px!important}
.po-alt-total-panel{padding:17px;border:1px solid #cad8ff;border-radius:16px;background:var(--eios-blue);margin-bottom:20px}.po-alt-total-panel>small{display:block;font-size:10px;letter-spacing:.1em;font-weight:600;color:#3b5887;margin-bottom:7px}.po-alt-total{font-family:var(--eios-display)!important;font-size:clamp(25px,2.2vw,36px);font-size:clamp(25px,14cqw,38px);font-weight:700;letter-spacing:-.035em;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.po-alt-difference{display:inline-block;min-height:0;margin:12px 0 0!important;padding:6px 10px;border-radius:20px;background:var(--eios-card);border:1px solid #c5d4ed;font-size:12px!important;font-weight:600}.po-alt-difference[data-tone=green]{color:#173457}.po-alt-card:has(.po-alt-quantity) .po-alt-difference{font-variant-numeric:tabular-nums}.po-alt-risk{display:inline-block;background:#fff1dc;color:#895000;border-radius:16px;padding:6px 10px;font-size:12px!important;line-height:1.35!important;margin:8px 0 0!important}
.po-alt-liquidity h5{font-size:10px;letter-spacing:.12em;font-weight:600;color:var(--eios-muted);margin:0 0 9px}.po-alt-cash-box{padding:11px 12px;border:1px solid var(--eios-line);border-radius:13px;margin:0 0 8px;background:var(--eios-card)}.po-alt-cash-box>p{color:var(--eios-muted);font-size:12px!important;margin:0 0 8px!important}.po-alt-cash-box strong{font-size:13px;font-weight:600}.po-alt-cash-box[data-tone=amber]{background:#fff3df;border-color:#ffd199;color:#935000}.po-alt-cash-box[data-tone=amber]>p{color:#935000}.po-alt-stress-ok{color:#13705a}.po-alt-cash{padding:0;background:transparent!important;font-size:13px;font-weight:600}.po-alt-cash::before{content:'✓'}.po-alt-cash[data-tone=red]::before{content:'△'}.po-alt-comparison{font-size:13px!important;line-height:1.5!important;color:var(--eios-muted);margin:9px 0 15px!important}.po-alt-card>details{border-color:var(--eios-line);margin:0 0 18px!important}.po-alt-card>details>summary{font-size:14px}.po-alt-card dl{display:grid;grid-template-columns:1fr 1fr;gap:10px}.po-alt-card dl>div{display:block;padding:11px;background:var(--eios-soft);border-radius:13px;margin:0;min-width:0}.po-alt-card dt{font-size:11px;font-weight:500;color:var(--eios-muted);margin-bottom:6px}.po-alt-card dd{text-align:left;color:var(--eios-ink);font-size:17px;font-weight:600;font-variant-numeric:tabular-nums}.po-alt-footer{margin:auto -22px -22px;padding:14px 22px;background:var(--eios-soft);border-top:1px solid var(--eios-line)}.po-alt-footer p{font-size:12px!important;margin:0!important;color:var(--eios-muted)}.po-alt-footer p:first-child{font-weight:600;color:var(--eios-ink);margin-bottom:4px!important}.po-alt-caption{color:var(--eios-muted)}.po-alt-methods{border-color:var(--eios-line)}
html[data-theme=dark]{--eios-bg:#0b1424;--eios-card:#121f33;--eios-soft:#192a43;--eios-ink:#e7eefb;--eios-muted:#acbdd7;--eios-line:#344663;--eios-blue:#20365d;--eios-ref:#081226;color-scheme:dark}
html[data-theme=dark] .po-purchase-summary .verdict{background:var(--eios-soft);color:var(--eios-ink)}
html[data-theme=dark] body{background:var(--eios-bg)!important;color:var(--eios-ink)!important}html[data-theme=dark] .sidebar{background:#080f1f}html[data-theme=dark] .topbar,html[data-theme=dark] .card,html[data-theme=dark] .review-card,html[data-theme=dark] .review-header,html[data-theme=dark] .po-step,html[data-theme=dark] .po-subsection,html[data-theme=dark] .po-cash,html[data-theme=dark] .po-save-progress,html[data-theme=dark] .po-save-technical,html[data-theme=dark] .po-treasury-chart{background:var(--eios-card)!important;border-color:var(--eios-line)!important;color:var(--eios-ink)!important}
html[data-theme=dark] h1,html[data-theme=dark] h2,html[data-theme=dark] h3,html[data-theme=dark] h4,html[data-theme=dark] .po-net,html[data-theme=dark] .po-row-label,html[data-theme=dark] .po-book-value,html[data-theme=dark] .po-column-total strong,html[data-theme=dark] .po-metric-value,html[data-theme=dark] .po-metric-ribbon strong{color:var(--eios-ink)!important}
html[data-theme=dark] input,html[data-theme=dark] select,html[data-theme=dark] textarea,html[data-theme=dark] #po-conditions .po-draft-column input,html[data-theme=dark] #po-conditions .po-draft-column select{background:#101b2d!important;border-color:#4b6080!important;color:var(--eios-ink)!important}
html[data-theme=dark] input:disabled,html[data-theme=dark] select:disabled,html[data-theme=dark] #po-conditions .po-book-disabled{background:#17263c!important;color:#b0c0d8!important;border-color:#344966!important}
html[data-theme=dark] .po-identity span{color:var(--eios-muted)!important}
html[data-theme=dark] .po-ribbons,html[data-theme=dark] .po-identity,html[data-theme=dark] .po-metric-ribbon,html[data-theme=dark] .po-source,html[data-theme=dark] .planning-item,html[data-theme=dark] .review-metrics>div,html[data-theme=dark] .po-purchase-summary,html[data-theme=dark] #po-study-state,html[data-theme=dark] .po-shared-conditions,html[data-theme=dark] .po-stock-assumptions,html[data-theme=dark] .po-stock-scenario,html[data-theme=dark] .po-quantity-review,html[data-theme=dark] .metric,html[data-theme=dark] .po-total,html[data-theme=dark] .po-cash-grid>div,html[data-theme=dark] #po-draft-origin{background:var(--eios-soft)!important;border-color:var(--eios-line)!important;color:var(--eios-ink)!important}
html[data-theme=dark] #po-conditions .po-negotiation-scroll{background:var(--eios-card);border-color:var(--eios-line)}html[data-theme=dark] #po-conditions .po-draft-column{background:transparent;color:var(--eios-ink)}html[data-theme=dark] #po-conditions .po-draft-column[aria-label="MI PROPUESTA"]{background:var(--eios-blue);border-color:#557dc9}html[data-theme=dark] #po-conditions .po-draft-column>header{background:transparent}html[data-theme=dark] #po-conditions .po-aligned-cell{border-color:var(--eios-line)}html[data-theme=dark] #po-conditions .po-tax-value,html[data-theme=dark] dt,html[data-theme=dark] .po-metric-label,html[data-theme=dark] .po-metric-unit:not(.po-ribbon-consumption-pending),html[data-theme=dark] .po-ribbon-meta,html[data-theme=dark] .po-heading p,html[data-theme=dark] .po-draft-column header p,html[data-theme=dark] small,html[data-theme=dark] figcaption{color:var(--eios-muted)!important}
html[data-theme=dark] .po-alt-total-panel{border-color:#4e6fac}html[data-theme=dark] .po-alt-total-panel>small{color:#b5cdf5!important}html[data-theme=dark] .po-alt-simulation{color:#b5cfff;border-color:#5178c3}html[data-theme=dark] .po-alt-difference{color:var(--eios-ink)}html[data-theme=dark] .po-alt-cash-box[data-tone=amber],html[data-theme=dark] .po-alt-risk,html[data-theme=dark] .po-save-status.is-action,html[data-theme=dark] .po-state-tile[data-tone=amber]{background:#3f301b!important;color:#ffd79a!important;border-color:#97753d!important}html[data-theme=dark] .po-alt-cash-box[data-tone=amber]>p{color:#ffd79a}html[data-theme=dark] .po-alt-stress-ok{color:#9be1bd}
html[data-theme=dark] .is-saving,html[data-theme=dark] .po-save-status.is-complete,html[data-theme=dark] .po-state-tile[data-tone=green],html[data-theme=dark] .po-purchase-summary[data-status=WITHIN_DECLARED_SCENARIO] .verdict{background:#153c2c!important;color:#b0efcb!important;border-color:#4a936c!important}html[data-theme=dark] .po-alt-cash[data-tone=green],html[data-theme=dark] .po-summary-stock[data-tone=green]{color:#a0e5be!important}html[data-theme=dark] .is-cost,html[data-theme=dark] .po-cash.is-short,html[data-theme=dark] .po-state-tile[data-tone=red],html[data-theme=dark] .po-save-status.is-conflict,html[data-theme=dark] .po-purchase-summary[data-status=SHORTFALL] .verdict{background:#47262b!important;color:#ffc3bd!important;border-color:#b47172!important}html[data-theme=dark] .po-date-warning,html[data-theme=dark] .po-alt-cash[data-tone=red],html[data-theme=dark] .po-summary-stock[data-tone=red]{color:#ffc3bd!important}
html[data-theme=dark] button,html[data-theme=dark] .po-nav a{background:#203554;color:var(--eios-ink);border-color:#4a6385}html[data-theme=dark] a,html[data-theme=dark] summary{color:#b4ceff}html[data-theme=dark] th{background:#203554!important;color:var(--eios-ink)!important}html[data-theme=dark] td{border-color:var(--eios-line)!important}html[data-theme=dark] tr{background:transparent!important}
html[data-theme=dark] .po-treasury-chart svg text{fill:var(--eios-muted)}html[data-theme=dark] .po-treasury-chart svg line[stroke="#e0e8f2"]{stroke:#344966}html[data-theme=dark] .po-treasury-chart svg path{stroke:#81adff}html[data-theme=dark] .po-treasury-chart svg circle{fill:#81adff}html[data-theme=dark] .po-treasury-chart .chart-legend span:first-child{color:#94baff}html[data-theme=dark] .po-treasury-chart .chart-legend span:last-child{color:#9be1bd}
@media(max-width:600px){.po-alternatives-table{padding:16px}.po-alt-heading{align-items:start}.po-alt-simulation{font-size:9px;padding:6px}.po-alt-card{padding:18px}.po-alt-footer{margin-left:-18px;margin-right:-18px;margin-bottom:-18px;padding:14px 18px}.po-alt-baseline{padding:16px}.po-alt-baseline strong{font-size:30px}}
'''
JS=r'''
(function(){const key='eios-appearance',root=document.documentElement;let stored=null;try{stored=localStorage.getItem(key)}catch{}const preference=matchMedia('(prefers-color-scheme: dark)'),button=document.createElement('button');button.type='button';button.id='eios-theme-toggle';document.querySelector('.topbar').append(button);function apply(theme){root.dataset.theme=theme;root.style.colorScheme=theme;button.textContent=theme==='dark'?'☀ Modo claro':'☾ Modo oscuro';button.setAttribute('aria-pressed',String(theme==='dark'));button.setAttribute('aria-label',theme==='dark'?'Activar modo claro':'Activar modo oscuro')}apply(stored==='dark'||stored==='light'?stored:preference.matches?'dark':'light');button.onclick=()=>{stored=root.dataset.theme==='dark'?'light':'dark';apply(stored);try{localStorage.setItem(key,stored)}catch{}};preference.addEventListener('change',event=>{if(stored!=='dark'&&stored!=='light')apply(event.matches?'dark':'light')});})();
'''
